export const displayName = 'Tela de Login';
export const screenSize = 'desktop';

import Btn from '@components/Btn';
import AlertBanner from '@components/AlertBanner';

export default function LoginScreen() {
  return (
    <div className="bg-background min-h-full flex flex-col font-body" style={{ minHeight: '600px' }}>
      {/* Header */}
      <div className="border-b border-border px-8 py-4">
        <span className="text-base font-semibold font-headings text-foreground">{t('Central de Processos')}</span>
      </div>

      {/* Content */}
      <div className="flex-1 flex items-center justify-center py-20">
        <div className="w-full max-w-sm flex flex-col gap-6">
          <div>
            <h1 className="text-2xl font-semibold font-headings text-foreground mb-2">{t('Entrar')}</h1>
            <p className="text-sm text-muted-foreground">{t('Acesse sua conta com o Google para continuar.')}</p>
          </div>

          {/* Login button */}
          <div className="border border-border p-6 flex flex-col gap-4">
            <button className="w-full flex items-center justify-center gap-3 border border-border bg-background px-4 py-3 text-sm font-medium text-foreground">
              <svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M17.64 9.205c0-.639-.057-1.252-.164-1.841H9v3.481h4.844a4.14 4.14 0 01-1.796 2.716v2.259h2.908c1.702-1.567 2.684-3.875 2.684-6.615z" fill="#4285F4"/>
                <path d="M9 18c2.43 0 4.467-.806 5.956-2.18l-2.908-2.259c-.806.54-1.837.86-3.048.86-2.344 0-4.328-1.584-5.036-3.711H.957v2.332A8.997 8.997 0 009 18z" fill="#34A853"/>
                <path d="M3.964 10.71A5.41 5.41 0 013.682 9c0-.593.102-1.17.282-1.71V4.958H.957A8.996 8.996 0 000 9c0 1.452.348 2.827.957 4.042l3.007-2.332z" fill="#FBBC05"/>
                <path d="M9 3.58c1.321 0 2.508.454 3.44 1.345l2.582-2.58C13.463.891 11.426 0 9 0A8.997 8.997 0 00.957 4.958L3.964 7.29C4.672 5.163 6.656 3.58 9 3.58z" fill="#EA4335"/>
              </svg>
              {t('Continuar com Google')}
            </button>
          </div>

          {/* Error state */}
          <AlertBanner variant="error">
            <span>{t('Não foi possível entrar. Verifique se o acesso ao Google está disponível e ')}<a className="underline">{t('tente novamente')}</a>{t('.')}</span>
          </AlertBanner>

          <p className="text-xs text-muted-foreground text-center">{t('Ao continuar, você concorda com os termos de uso da plataforma.')}</p>
        </div>
      </div>
    </div>
  );
}

export const displayName = 'Seleção de Vínculo';
export const screenSize = 'desktop';

import AlertBanner from '@components/AlertBanner';
import Btn from '@components/Btn';
import Badge from '@components/Badge';
import Icon from '@global/Icon';

const vinculos = [
  {
    name: 'Souza & Associados Advocacia',
    role: t('Titular'),
    type: 'escritorio',
    active: true,
  },
  {
    name: 'Ferreira, Lima e Rodrigues Advogados',
    role: t('Membro da equipe'),
    type: 'escritorio',
    active: false,
  },
  {
    name: 'Rafael Mendonça Souza (pessoal)',
    role: t('Titular'),
    type: 'pessoal',
    active: false,
  },
];

export default function VinculationScreen() {
  return (
    <div className="bg-background font-body" style={{ minHeight: '600px' }}>
      <div className="border-b border-border px-8 py-4 flex items-center justify-between">
        <span className="text-base font-semibold font-headings text-foreground">{t('Central de Processos')}</span>
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center">
            <Icon i="user" size={14} />
          </div>
          <span className="text-sm text-foreground">{t('Rafael Mendonça Souza')}</span>
          <a className="text-xs text-muted-foreground underline ml-1">{t('sair')}</a>
        </div>
      </div>

      <div className="flex items-start justify-center py-12 px-4">
        <div className="w-full max-w-lg flex flex-col gap-6">
          <div>
            <h1 className="text-2xl font-semibold font-headings text-foreground mb-1">{t('Selecionar vínculo')}</h1>
            <p className="text-sm text-muted-foreground">{t('Escolha em qual contexto profissional você quer trabalhar agora.')}</p>
          </div>

          <div className="border border-border flex flex-col">
            {vinculos.map((v, i) => (
              <div
                key={i}
                className={`flex items-center justify-between px-5 py-4 border-b border-border last:border-b-0 ${v.active ? 'bg-secondary' : 'bg-background'}`}
              >
                <div className="flex flex-col gap-0.5">
                  <div className="flex items-center gap-2">
                    <Icon i={v.type === 'pessoal' ? 'user' : 'building-2'} size={15} />
                    <span className="text-sm font-medium text-foreground">{v.name}</span>
                    {v.active && <Badge label={t('Atual')} variant="active" />}
                  </div>
                  <span className="text-xs text-muted-foreground ml-5">{v.role}</span>
                </div>
                {!v.active && (
                  <button className="text-sm font-medium text-accent underline flex-shrink-0">{t('Selecionar')}</button>
                )}
              </div>
            ))}

            {/* Unavailable vínculo example */}
            <div className="flex items-center justify-between px-5 py-4 bg-background opacity-50">
              <div className="flex flex-col gap-0.5">
                <div className="flex items-center gap-2">
                  <Icon i="building-2" size={15} />
                  <span className="text-sm font-medium text-foreground">{t('Costa & Silva Advocacia')}</span>
                  <Badge label={t('Indisponível')} variant="muted" />
                </div>
                <span className="text-xs text-muted-foreground ml-5">{t('Membro da equipe')}</span>
              </div>
            </div>
          </div>

          <AlertBanner variant="warning">
            {t('Um dos vínculos está indisponível. Entre em contato com o titular para verificar o status da sua credencial.')}
          </AlertBanner>

          {/* Session error state */}
          <AlertBanner variant="error">
            {t('Sua sessão não está mais válida. ')}<a className="underline">{t('Entre novamente')}</a>{t(' para continuar.')}
          </AlertBanner>
        </div>
      </div>
    </div>
  );
}

export const displayName = 'Dashboard';
export const screenSize = 'desktop';

import TopBar from '@components/TopBar';
import MetricCard from '@components/MetricCard';
import AlertBanner from '@components/AlertBanner';
import PageShell from '@components/PageShell';
import SectionHeader from '@components/SectionHeader';
import Icon from '@global/Icon';

const periods = [
  { label: t('Hoje'), key: 'hoje' },
  { label: t('Esta semana'), key: 'semana' },
  { label: t('Últimos 7 dias'), key: '7dias' },
];

const tribunalAlerts = [
  { name: t('TJSP — Tribunal de Justiça de São Paulo'), since: t('Falha desde 09/07/2025, 03h12 (Brasília)') },
  { name: t('TRF-3 — Tribunal Regional Federal da 3ª Região'), since: t('Falha desde 09/07/2025, 06h44 (Brasília)') },
];

export default function DashboardScreen() {
  return (
    <div className="bg-background font-body">
      <TopBar activeTab="dashboard" />

      <PageShell maxWidth="max-w-5xl">
        {/* Page title */}
        <div className="mb-6">
          <h1 className="text-xl font-semibold font-headings text-foreground">{t('Dashboard')}</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{t('Atualizado às 10h31 de 09/07/2025 — fuso de Brasília (UTC−3)')}</p>
        </div>

        {/* Tribunal failure alerts */}
        {tribunalAlerts.length > 0 && (
          <div className="flex flex-col gap-2 mb-8">
            <p className="text-sm font-medium text-foreground mb-1">{t('Alertas de coleta')}</p>
            {tribunalAlerts.map((a, i) => (
              <AlertBanner key={i} variant="error">
                <span className="font-medium">{a.name}</span>
                {t(' — coleta com falha. ')}<span className="font-mono text-xs">{a.since}</span>
                {t(' Os números exibidos abaixo podem estar incompletos para este tribunal.')}
              </AlertBanner>
            ))}
          </div>
        )}

        {/* Periods */}
        {periods.map((period) => (
          <div key={period.key} className="mb-8">
            <SectionHeader title={period.label} />
            <div className="grid grid-cols-2 gap-4">
              {period.key === 'hoje' && (
                <>
                  <MetricCard
                    label={t('Comunicações novas')}
                    value="14"
                    period={t('publicações coletadas')}
                    state="value"
                  />
                  <MetricCard
                    label={t('Processos distintos associados')}
                    value="9"
                    period={t('processos com ao menos 1 comunicação')}
                    state="value"
                  />
                </>
              )}
              {period.key === 'semana' && (
                <>
                  <MetricCard
                    label={t('Comunicações novas')}
                    value="—"
                    period={t('coleta em andamento')}
                    state="loading"
                    note={t('Resultado parcial disponível — coleta ainda não finalizada.')}
                  />
                  <MetricCard
                    label={t('Processos distintos associados')}
                    value="—"
                    period={t('coleta em andamento')}
                    state="loading"
                  />
                </>
              )}
              {period.key === '7dias' && (
                <>
                  <MetricCard
                    label={t('Comunicações novas')}
                    value="*"
                    period={t('acesso restrito')}
                    state="restricted"
                    note={t('Sem permissão para visualizar este período.')}
                  />
                  <MetricCard
                    label={t('Processos distintos associados')}
                    value="0"
                    period={t('nenhum processo associado no período')}
                    state="value"
                  />
                </>
              )}
            </div>
          </div>
        ))}

        {/* No work state note */}
        <div className="border border-border bg-input p-4">
          <p className="text-sm text-muted-foreground">
            <Icon i="info" size={14} className="inline mr-1.5 text-info" />
            {t('Nenhum monitoramento ativo cadastrado. Configure monitoramentos para começar a receber comunicações.')}
          </p>
        </div>
      </PageShell>
    </div>
  );
}

export const displayName = 'Comunicações';
export const screenSize = 'desktop';

import TopBar from '@components/TopBar';
import PageShell from '@components/PageShell';
import SectionHeader from '@components/SectionHeader';
import CommunicationRow from '@components/CommunicationRow';
import AlertBanner from '@components/AlertBanner';
import EmptyState from '@components/EmptyState';

const groups = [
  {
    tribunal: t('TJMG — Tribunal de Justiça de Minas Gerais'),
    items: [
      {
        processo: '0012345-67.2023.8.13.0024',
        resumo: t('Intimação para manifestação no prazo de 15 dias, nos termos do art. 351 do CPC. Processo n.º 0012345-67.2023.8.13.0024 — 2ª Vara Cível da Comarca de Belo Horizonte.'),
        data: '09/07/2025',
        duplicidade: false,
      },
      {
        processo: '0012345-67.2023.8.13.0024',
        resumo: t('Despacho de juntada de petição e encaminhamento para vista ao Ministério Público. Processo n.º 0012345-67.2023.8.13.0024 — 2ª Vara Cível da Comarca de Belo Horizonte.'),
        data: '09/07/2025',
        duplicidade: true,
      },
      {
        processo: '',
        resumo: t('Publicação de pauta de audiência para o dia 25/08/2025 às 14h00. Parte interessada: Rafael Mendonça Souza — OAB/MG 123.456. Número do processo não identificado na publicação.'),
        data: '08/07/2025',
        duplicidade: false,
      },
    ],
  },
  {
    tribunal: t('TRT-3 — Tribunal Regional do Trabalho da 3ª Região'),
    items: [
      {
        processo: '0001122-33.2024.5.03.0001',
        resumo: t('Mandado de citação expedido. Réu: Comércio Estrela Ltda. Autor representado por Rafael Mendonça Souza — OAB/MG 123.456. Prazo de resposta: 20 dias úteis.'),
        data: '07/07/2025',
        duplicidade: false,
      },
    ],
  },
];

export default function ComunicacoesScreen() {
  return (
    <div className="bg-background font-body">
      <TopBar activeTab="comunicacoes" />

      <PageShell maxWidth="max-w-4xl">
        <div className="mb-6">
          <h1 className="text-xl font-semibold font-headings text-foreground">{t('Comunicações')}</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{t('Publicações judiciais coletadas para seus monitoramentos. Agrupadas por tribunal.')}</p>
        </div>

        <AlertBanner variant="info">
          {t('A lista abaixo não representa necessariamente o total de publicações — a coleta pode estar em andamento para alguns tribunais.')}
        </AlertBanner>

        <div className="mt-6 flex flex-col gap-8">
          {groups.map((group, gi) => (
            <div key={gi}>
              <div className="bg-secondary border border-border px-5 py-2.5">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">{group.tribunal}</p>
              </div>
              <div className="border border-t-0 border-border flex flex-col">
                {group.items.map((item, ii) => (
                  <CommunicationRow
                    key={ii}
                    processo={item.processo}
                    resumo={item.resumo}
                    data={item.data}
                    duplicidade={item.duplicidade}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Empty state (shown when no items) */}
        <div className="mt-8 border border-border">
          <EmptyState
            icon="mail"
            title={t('Nenhuma comunicação encontrada')}
            description={t('Não há publicações coletadas para o período selecionado. Isso não indica que a coleta foi concluída.')}
          />
        </div>

        {/* Error state */}
        <div className="mt-4">
          <AlertBanner variant="error">
            {t('Não foi possível carregar as comunicações. ')}<a className="underline">{t('Tentar novamente')}</a>
          </AlertBanner>
        </div>

        {/* Restricted state */}
        <div className="mt-4">
          <AlertBanner variant="warning">
            {t('Você não tem permissão para visualizar comunicações deste contexto.')}
          </AlertBanner>
        </div>
      </PageShell>
    </div>
  );
}

export const displayName = 'Monitoramentos';
export const screenSize = 'desktop';

import TopBar from '@components/TopBar';
import PageShell from '@components/PageShell';
import SectionHeader from '@components/SectionHeader';
import MonitoringRow from '@components/MonitoringRow';
import Btn from '@components/Btn';
import AlertBanner from '@components/AlertBanner';
import Badge from '@components/Badge';

const partesMonitoradas = [
  { name: t('PETROBRAS — Petróleo Brasileiro S.A.'), tribunals: t('TJSP, TJRJ, TRF-2'), status: 'ativo' },
  { name: t('Maria Aparecida da Silva'), tribunals: t('Todos os tribunais'), status: 'ativo' },
  { name: t('Construtora Horizonte Ltda.'), tribunals: t('TJMG, TRT-3'), status: 'inativo' },
];

const processosMonitorados = [
  { name: '0012345-67.2023.8.13.0024', tribunals: t('TJMG'), status: 'ativo' },
  { name: '0007891-23.2022.5.03.0001', tribunals: t('TRT-3'), status: 'ativo' },
  { name: '1234567-89.2021.4.03.6100', tribunals: t('TRF-3'), status: 'inativo' },
];

export default function MonitoramentosScreen() {
  return (
    <div className="bg-background font-body">
      <TopBar activeTab="monitoramentos" />

      <PageShell maxWidth="max-w-4xl">
        <div className="mb-6">
          <h1 className="text-xl font-semibold font-headings text-foreground">{t('Monitoramentos')}</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{t('Gerencie os dados usados para rastrear publicações: dados do advogado, partes e processos.')}</p>
        </div>

        {/* Advogado */}
        <div className="mb-8">
          <SectionHeader title={t('Dados do advogado')} subtitle={t('Informações do seu perfil usadas no monitoramento automático.')} />
          <div className="border border-border p-5 flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-foreground">{t('Rafael Mendonça Souza')}</p>
                <p className="text-xs text-muted-foreground mt-0.5">{t('OAB/MG 123.456 (principal) · OAB/SP 87.432 (secundária)')}</p>
              </div>
              <Badge label={t('Monitoramento ativo')} variant="active" />
            </div>
            <p className="text-xs text-muted-foreground border-t border-border pt-3">
              {t('Os dados exibidos acima fazem parte do seu perfil. Para alterá-los, edite seu perfil nas configurações da conta.')}
            </p>
          </div>
        </div>

        {/* Partes monitoradas */}
        <div className="mb-8">
          <SectionHeader
            title={t('Partes monitoradas')}
            subtitle={t('Nomes de pessoas ou empresas a acompanhar nas publicações.')}
            action={<Btn variant="primary" size="sm" icon="plus">{t('Nova parte')}</Btn>}
          />
          <div className="border border-border flex flex-col">
            {partesMonitoradas.map((p, i) => (
              <MonitoringRow key={i} name={p.name} tribunals={p.tribunals} status={p.status} />
            ))}
          </div>
        </div>

        {/* Processos monitorados */}
        <div className="mb-8">
          <SectionHeader
            title={t('Processos monitorados')}
            subtitle={t('Números CNJ de processos a acompanhar.')}
            action={<Btn variant="primary" size="sm" icon="plus">{t('Novo processo')}</Btn>}
          />
          <div className="border border-border flex flex-col">
            {processosMonitorados.map((p, i) => (
              <MonitoringRow key={i} name={p.name} tribunals={p.tribunals} status={p.status} />
            ))}
          </div>
        </div>

        {/* Error state */}
        <AlertBanner variant="error">
          {t('Não foi possível carregar os monitoramentos. ')}<a className="underline">{t('Tentar novamente')}</a>
        </AlertBanner>
      </PageShell>
    </div>
  );
}

export const displayName = 'Parte Monitorada — Cadastro e Edição';
export const screenSize = 'desktop';

import TopBar from '@components/TopBar';
import PageShell from '@components/PageShell';
import FormField from '@components/FormField';
import TextInput from '@components/TextInput';
import AlertBanner from '@components/AlertBanner';
import Btn from '@components/Btn';
import Badge from '@components/Badge';
import Icon from '@global/Icon';

const tribunais = [
  { code: 'TJMG', label: t('TJMG — Minas Gerais'), selected: true },
  { code: 'TJSP', label: t('TJSP — São Paulo'), selected: true },
  { code: 'TJRJ', label: t('TJRJ — Rio de Janeiro'), selected: false },
  { code: 'TRT-3', label: t('TRT-3 — TRT da 3ª Região'), selected: false },
  { code: 'TRF-3', label: t('TRF-3 — TRF da 3ª Região'), selected: false },
];

export default function ParteDetalheScreen() {
  return (
    <div className="bg-background font-body">
      <TopBar activeTab="monitoramentos" />

      <PageShell maxWidth="max-w-2xl">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-muted-foreground mb-6">
          <a className="underline text-accent">{t('Monitoramentos')}</a>
          <Icon i="chevron-right" size={13} />
          <span>{t('Parte monitorada')}</span>
        </div>

        <div className="flex items-start justify-between mb-4">
          <h1 className="text-xl font-semibold font-headings text-foreground">{t('Editar parte monitorada')}</h1>
          <Badge label={t('Ativa')} variant="active" />
        </div>

        <div className="flex flex-col gap-5">
          <AlertBanner variant="warning">
            {t('Já existe uma parte com nome similar: "PETROBRAS S.A.". Verifique antes de salvar para evitar monitoramentos duplicados. O sistema não identifica homônimos automaticamente.')}
          </AlertBanner>

          <div className="border border-border p-5 flex flex-col gap-5">
            <FormField label={t('Nome da parte')} required={true} error="">
              <TextInput value="PETROBRAS — Petróleo Brasileiro S.A." />
            </FormField>

            <div>
              <FormField label={t('Tribunais')} hint={t('Sem seleção específica, o monitoramento abrange todos os tribunais disponíveis. Uma seleção explícita não pode ficar vazia.')}>
                <div className="flex flex-col gap-2 mt-2">
                  {tribunais.map((t_item) => (
                    <div key={t_item.code} className={`flex items-center gap-3 px-3 py-2.5 border ${t_item.selected ? 'border-foreground bg-secondary' : 'border-border bg-background'}`}>
                      <div className={`w-4 h-4 border flex items-center justify-center flex-shrink-0 ${t_item.selected ? 'border-foreground bg-foreground' : 'border-border'}`}>
                        {t_item.selected && <Icon i="check" size={10} className="text-primary-foreground" />}
                      </div>
                      <span className="text-sm text-foreground">{t_item.label}</span>
                    </div>
                  ))}
                </div>
              </FormField>
            </div>
          </div>

          {/* Save error */}
          <AlertBanner variant="error">
            {t('Erro ao salvar. Verifique sua conexão e tente novamente. Os dados preenchidos foram mantidos.')}
          </AlertBanner>

          {/* No permission */}
          <AlertBanner variant="warning">
            {t('Você não tem permissão para editar ou desativar partes monitoradas.')}
          </AlertBanner>

          <div className="flex items-center justify-between gap-3 border-t border-border pt-5">
            <button className="text-sm text-error underline">{t('Desativar parte')}</button>
            <div className="flex gap-3">
              <Btn variant="secondary">{t('Cancelar')}</Btn>
              <Btn variant="primary">{t('Salvar alterações')}</Btn>
            </div>
          </div>
        </div>
      </PageShell>
    </div>
  );
}

export const displayName = 'Dashboard — Mobile';
export const screenSize = 'mobile';

import TopBarMobile from '@components/TopBarMobile';
import MetricCard from '@components/MetricCard';
import AlertBanner from '@components/AlertBanner';
import Icon from '@global/Icon';

export default function DashboardMobileScreen() {
  return (
    <div className="bg-background font-body">
      <TopBarMobile activeTab="dashboard" />

      <div className="px-4 py-5 flex flex-col gap-5">
        {/* Context */}
        <div className="flex items-center gap-2 text-xs text-muted-foreground border-b border-border pb-3">
          <Icon i="building-2" size={13} />
          <span>{t('Souza & Associados')}</span>
          <a className="text-accent underline ml-auto">{t('trocar')}</a>
        </div>

        <p className="text-xs text-muted-foreground">{t('Atualizado às 10h31 de 09/07/2025 — Brasília (UTC−3)')}</p>

        {/* Alert */}
        <AlertBanner variant="error">
          <span className="font-medium">{t('TJSP')}</span>{t(' — coleta com falha desde 09/07, 03h12.')}
        </AlertBanner>

        {/* Hoje */}
        <div>
          <p className="text-xs font-medium text-foreground mb-2 uppercase tracking-wide">{t('Hoje')}</p>
          <div className="grid grid-cols-2 gap-3">
            <MetricCard label={t('Comunicações novas')} value="14" period={t('publicações')} />
            <MetricCard label={t('Processos distintos')} value="9" period={t('processos')} />
