@theme {
  /* used via utility-classes, bg-background, text-primary, and many more */
  --color-background: #ffffff;
  --color-foreground: #111111;
  --color-border: #d4d4d4;
  --color-input: #f5f5f5;
  --color-primary: #111111;
  --color-primary-foreground: #ffffff;
  --color-secondary: #f0f0f0;
  --color-secondary-foreground: #111111;
  --color-muted: #e8e8e8;
  --color-muted-foreground: #737373;
  --color-accent: #2563eb;
  --color-accent-foreground: #ffffff;
  --color-success: #16a34a;
  --color-success-bg: #f0fdf4;
  --color-warning: #b45309;
  --color-warning-bg: #fffbeb;
  --color-error: #dc2626;
  --color-error-bg: #fef2f2;
  --color-info: #0369a1;
  --color-info-bg: #f0f9ff;
  --color-nav-bg: #fafafa;
  --color-table-row-alt: #fafafa;

  /* DO NOT REMOVE: these radius variables are required by the theme editor. */
  --radius-sm: 2px;
  --radius-md: 2px;
  --radius-lg: 2px;
  --radius-xl: 2px;

  /* DONT CHANGE OR REMOVE THIS VARIABLE */
  --radius: var(--radius-sm);

  /* DO NOT REMOVE: these font variables are required by the theme editor. */
  /* available fonts: "Inter", "DM Sans", "Nunito", "PT Serif", "Space Grotesk", "IBM Plex Mono", "IBM Plex Sans", "Roboto Slab", "Geist", "Shantell Sans" */
  --font-body: IBM Plex Sans;
  --font-headings: IBM Plex Sans;

  /* Add and change text sizes as you see fit */
  --text-xs: 11px;
  --text-sm: 13px;
  --text-base: 14px;
  --text-lg: 16px;
  --text-xl: 18px;
  --text-2xl: 22px;
  --text-3xl: 28px;
  --text-4xl: 36px;
}

import Icon from '@global/Icon';

export const displayName = 'Button';
export const shortDescription = 'Primary, secondary, ghost, and danger buttons';

const variants = {
  primary: 'bg-primary text-primary-foreground border border-primary',
  secondary: 'bg-background text-foreground border border-border',
  ghost: 'bg-transparent text-muted-foreground border border-transparent',
  danger: 'bg-error text-primary-foreground border border-error',
  accent: 'bg-accent text-accent-foreground border border-accent',
};

const sizes = {
  sm: 'px-3 py-1.5 text-xs',
  md: 'px-4 py-2 text-sm',
  lg: 'px-5 py-2.5 text-base',
};

export default function Btn({
  children = 'Botão',
  variant = 'primary',
  size = 'md',
  icon = '',
  disabled = false,
}) {
  return (
    <button
      className={`inline-flex items-center gap-2 font-medium font-body ${variants[variant] || variants.primary} ${sizes[size] || sizes.md} ${disabled ? 'opacity-40' : ''}`}
    >
      {icon && <Icon i={icon} size={14} />}
      {children}
    </button>
  );
}

import Icon from '@global/Icon';

export const displayName = 'Alert Banner';
export const shortDescription = 'Inline alert for warnings, errors, success, info';

const styles = {
  warning: 'bg-warning-bg border-warning text-warning',
  error: 'bg-error-bg border-error text-error',
  success: 'bg-success-bg border-success text-success',
  info: 'bg-info-bg border-info text-info',
};

const icons = {
  warning: 'alert-triangle',
  error: 'alert-circle',
  success: 'check-circle',
  info: 'info',
};

export default function AlertBanner({ variant = 'info', children = 'Mensagem informativa.' }) {
  return (
    <div className={`flex items-start gap-3 border px-4 py-3 text-sm font-body ${styles[variant] || styles.info}`}>
      <Icon i={icons[variant] || 'info'} size={16} className="mt-0.5 flex-shrink-0" />
      <div>{children}</div>
    </div>
  );
}

import Icon from '@global/Icon';

export const displayName = 'Form Field';
export const shortDescription = 'Labeled form field with optional error state';

export default function FormField({
  label = 'Campo',
  hint = '',
  error = '',
  required = false,
  children = null,
}) {
  return (
    <div className="flex flex-col gap-1 font-body">
      <label className="text-sm font-medium text-foreground">
        {label}
        {required && <span className="text-error ml-1">*</span>}
      </label>
      {hint && <p className="text-xs text-muted-foreground">{hint}</p>}
      {children}
      {error && (
        <p className="text-xs text-error flex items-center gap-1 mt-0.5">
          <Icon i="alert-circle" size={12} />
          {error}
        </p>
      )}
    </div>
  );
}

export const displayName = 'Text Input';
export const shortDescription = 'Styled div mimicking a text input';

export default function TextInput({
  value = '',
  placeholder = '',
  hasError = false,
  disabled = false,
}) {
  return (
    <div
      className={`border px-3 py-2 text-sm font-body bg-input text-foreground
        ${hasError ? 'border-error' : 'border-border'}
        ${disabled ? 'opacity-50' : ''}
      `}
    >
      {value || <span className="text-muted-foreground">{placeholder}</span>}
    </div>
  );
}

export const displayName = 'Status Badge';
export const shortDescription = 'Small status/label badge';

const variants = {
  success: 'bg-success-bg text-success border border-success',
  warning: 'bg-warning-bg text-warning border border-warning',
  error: 'bg-error-bg text-error border border-error',
  info: 'bg-info-bg text-info border border-info',
  muted: 'bg-muted text-muted-foreground border border-border',
  active: 'bg-success-bg text-success border border-success',
  inactive: 'bg-muted text-muted-foreground border border-border',
};

export default function Badge({ label = 'Ativo', variant = 'muted' }) {
  return (
    <span className={`inline-flex items-center px-2 py-0.5 text-xs font-medium ${variants[variant] || variants.muted}`}>
      {label}
    </span>
  );
}

import Icon from '@global/Icon';

export const displayName = 'Top Bar';
export const shortDescription = 'Navigation top bar with tabs and user context';

const navItems = [
  { label: t('Dashboard'), id: 'dashboard' },
  { label: t('Comunicações'), id: 'comunicacoes' },
  { label: t('Monitoramentos'), id: 'monitoramentos' },
  { label: t('Equipe e grupos'), id: 'equipe' },
];

export default function TopBar({
  activeTab = 'dashboard',
  userName = 'Dr. Rafael Souza',
  vinculation = 'Souza & Associados Advocacia',
  showVinculationSwitch = true,
}) {
  return (
    <header className="bg-background border-b border-border w-full font-body">
      {/* Top row */}
      <div className="flex items-center justify-between px-8 py-3 border-b border-border">
        <div className="flex items-center gap-3">
          <span className="text-base font-headings font-semibold tracking-tight text-foreground">{t('Central de Processos')}</span>
        </div>
        <div className="flex items-center gap-4">
          {showVinculationSwitch && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Icon i="building-2" size={14} />
              <span>{vinculation}</span>
              <a className="text-accent underline text-xs ml-1">{t('trocar')}</a>
            </div>
          )}
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center">
              <Icon i="user" size={14} />
            </div>
            <span className="text-sm text-foreground">{userName}</span>
            <a className="text-xs text-muted-foreground underline ml-1">{t('sair')}</a>
          </div>
        </div>
      </div>
      {/* Nav tabs */}
      <nav className="flex items-center gap-0 px-8">
        {navItems.map((item) => (
          <a
            key={item.id}
            className={`px-4 py-3 text-sm font-medium border-b-2 transition-none ${
              activeTab === item.id
                ? 'border-foreground text-foreground'
                : 'border-transparent text-muted-foreground'
            }`}
          >
            {item.label}
          </a>
        ))}
      </nav>
    </header>
  );
}

export const displayName = 'Metric Card';
export const shortDescription = 'Dashboard metric card with value, label and period';

const stateStyles = {
  value: 'text-foreground',
  loading: 'text-muted-foreground',
  error: 'text-error',
  restricted: 'text-muted-foreground',
  partial: 'text-warning',
};

export default function MetricCard({
  label = 'Métrica',
  value = '0',
  period = 'hoje',
  state = 'value', // 'value' | 'loading' | 'error' | 'restricted' | 'partial'
  note = '',
}) {
  const displayValue = state === 'restricted' ? '*' : state === 'loading' ? '—' : value;
  const valueClass = stateStyles[state] || stateStyles.value;

  return (
    <div className="border border-border bg-background p-5 flex flex-col gap-2 font-body">
      <p className="text-sm text-muted-foreground">{label}</p>
      <p className={`text-3xl font-semibold font-headings ${valueClass}`}>{displayValue}</p>
      <p className="text-xs text-muted-foreground">{period}</p>
      {note && <p className="text-xs text-muted-foreground border-t border-border pt-2 mt-1">{note}</p>}
    </div>
  );
}

export const displayName = 'Page Shell';
export const shortDescription = 'Page wrapper with padding and max width';

export default function PageShell({ children, maxWidth = 'max-w-5xl' }) {
  return (
    <main className={`w-full ${maxWidth} mx-auto px-8 py-8 font-body`}>
      {children}
    </main>
  );
}

export const displayName = 'Section Header';
export const shortDescription = 'Section title with optional subtitle and action';

export default function SectionHeader({
  title = 'Seção',
  subtitle = '',
  action = null,
}) {
  return (
    <div className="flex items-start justify-between gap-4 mb-4 font-body">
      <div>
        <h2 className="text-lg font-semibold text-foreground font-headings">{title}</h2>
        {subtitle && <p className="text-sm text-muted-foreground mt-0.5">{subtitle}</p>}
      </div>
      {action && <div className="flex-shrink-0">{action}</div>}
    </div>
  );
}

import Icon from '@global/Icon';

export const displayName = 'Communication Row';
export const shortDescription = 'Single row in the communications list';

export default function CommunicationRow({
  processo = '',
  tribunal = '',
  resumo = '',
  data = '',
  duplicidade = false,
}) {
  return (
    <div className="border-b border-border px-5 py-4 flex flex-col gap-1.5 font-body">
      <div className="flex items-start justify-between gap-4">
        <div className="flex flex-col gap-0.5">
          {processo && (
            <span className="text-xs text-muted-foreground font-mono">
              {processo}
            </span>
          )}
          <p className="text-sm text-foreground leading-relaxed">{resumo}</p>
        </div>
        <div className="flex-shrink-0 flex flex-col items-end gap-1">
          <span className="text-xs text-muted-foreground">{data}</span>
          <a className="text-xs text-accent underline">{t('abrir comunicação')}</a>
        </div>
      </div>
      {duplicidade && (
        <div className="flex items-center gap-1.5 text-xs text-warning mt-1">
          <Icon i="alert-triangle" size={12} />
          <span>{t('Possível duplicidade — aguardando verificação')}</span>
        </div>
      )}
    </div>
  );
}

import Icon from '@global/Icon';

export const displayName = 'Empty State';
export const shortDescription = 'Empty/no-data state with icon, title and description';

export default function EmptyState({
  icon = 'inbox',
  title = 'Nenhum dado encontrado',
  description = '',
  action = null,
}) {
  return (
    <div className="flex flex-col items-center justify-center py-16 gap-3 font-body text-center">
      <div className="text-muted-foreground">
        <Icon i={icon} size={36} />
      </div>
      <p className="text-base font-medium text-foreground">{title}</p>
      {description && <p className="text-sm text-muted-foreground max-w-xs">{description}</p>}
      {action}
    </div>
  );
}

export const displayName = 'Monitoring Row';
export const shortDescription = 'Single row in monitored parties or processes list';

import Badge from '@components/Badge';

export default function MonitoringRow({
  name = '',
  tribunals = 'Todos os tribunais',
  status = 'ativo',
  detail = true,
}) {
  return (
    <div className="border-b border-border px-5 py-3.5 flex items-center justify-between gap-4 font-body">
      <div className="flex flex-col gap-0.5 flex-1 min-w-0">
        <span className="text-sm text-foreground font-medium truncate">{name}</span>
        <span className="text-xs text-muted-foreground">{tribunals}</span>
      </div>
      <div className="flex items-center gap-3 flex-shrink-0">
        <Badge label={status === 'ativo' ? t('Ativo') : t('Inativo')} variant={status === 'ativo' ? 'active' : 'inactive'} />
        {detail && <a className="text-xs text-accent underline">{t('detalhe')}</a>}
      </div>
    </div>
  );
}

import Icon from '@global/Icon';

export const displayName = 'Top Bar Mobile';
export const shortDescription = 'Mobile navigation top bar with tab strip';

export default function TopBarMobile({
  activeTab = 'dashboard',
  userName = 'Dr. Rafael Souza',
}) {
  const navItems = [
    { label: t('Dashboard'), id: 'dashboard' },
    { label: t('Comunicações'), id: 'comunicacoes' },
    { label: t('Monitoramentos'), id: 'monitoramentos' },
    { label: t('Equipe'), id: 'equipe' },
  ];

  return (
    <header className="bg-background border-b border-border w-full font-body">
      <div className="flex items-center justify-between px-4 py-3">
        <span className="text-base font-semibold font-headings text-foreground">{t('Central de Processos')}</span>
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center">
            <Icon i="user" size={14} />
          </div>
        </div>
      </div>
      <nav className="flex overflow-x-auto border-b border-border">
        {navItems.map((item) => (
          <a
            key={item.id}
            className={`flex-shrink-0 px-4 py-2 text-sm font-medium border-b-2 ${
              activeTab === item.id
                ? 'border-foreground text-foreground'
                : 'border-transparent text-muted-foreground'
            }`}
          >
            {item.label}
          </a>
        ))}
      </nav>
    </header>
  );
}

export const displayName = 'Team Member Row';
export const shortDescription = 'Row in the team/credentials list';

import Badge from '@components/Badge';

export default function TeamMemberRow({
  name = 'Membro',
  email = '',
  credentialStatus = 'ativa',
  validity = '',
  groups = [],
}) {
  const statusVariant = {
    ativa: 'active',
    expirada: 'warning',
    revogada: 'error',
    pendente: 'info',
  }[credentialStatus] || 'muted';

  const statusLabel = {
    ativa: t('Ativa'),
    expirada: t('Expirada'),
    revogada: t('Revogada'),
    pendente: t('Convite pendente'),
  }[credentialStatus] || credentialStatus;

  return (
    <div className="border-b border-border px-5 py-3.5 flex items-center justify-between gap-4 font-body">
      <div className="flex flex-col gap-0.5 flex-1 min-w-0">
        <span className="text-sm font-medium text-foreground">{name}</span>
        <span className="text-xs text-muted-foreground">{email}</span>
        {groups.length > 0 && (
          <div className="flex gap-1 flex-wrap mt-1">
            {groups.map((g, i) => (
              <span key={i} className="bg-secondary text-secondary-foreground px-1.5 py-0.5 text-xs border border-border">{g}</span>
            ))}
          </div>
        )}
      </div>
      <div className="flex items-center gap-3 flex-shrink-0">
        <Badge label={statusLabel} variant={statusVariant} />
        {validity && <span className="text-xs text-muted-foreground">{validity}</span>}
        <a className="text-xs text-accent underline">{t('gerenciar')}</a>
      </div>
    </div>
  );
}
